"use client";
import { useEffect, useState } from "react";
import { 
  Trash2, Plus, Users, MessageSquare, Loader2, X, AlertTriangle, CheckCircle2, Eye 
} from "lucide-react";

export default function AdminDashboard() {
  const [data, setData] = useState<any>({ stats: [], messages: [] });
  const [loading, setLoading] = useState(true);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [selectedMessage, setSelectedMessage] = useState<any>(null);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  const fetchData = async () => {
    setLoading(true);
    try {
      const res = await fetch("/api/admin/stats");
      const resData = await res.json();
      setData(resData);
    } catch (err) {
      showNotify("Veriler yüklenemedi!", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  const showNotify = (msg: string, type: 'success' | 'error') => {
    setNotification({ msg, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleDelete = async () => {
    if (!confirmDelete) return;
    
    try {
      console.log("Silme isteği gönderiliyor ID:", confirmDelete);
      const res = await fetch(`/api/admin/users/${confirmDelete}`, { 
        method: "DELETE",
        headers: { "Content-Type": "application/json" }
      });

      const result = await res.json();

      if (res.ok) {
        showNotify("Kullanıcı ve tüm verileri imha edildi.", "success");
        // Arayüzü anında güncelle
        setData((prev: any) => ({
          ...prev,
          stats: prev.stats.filter((u: any) => u.id !== confirmDelete)
        }));
      } else {
        showNotify(result.error || "Silme işlemi başarısız!", "error");
      }
    } catch (err) {
      console.error("Silme hatası:", err);
      showNotify("Sunucu bağlantı hatası!", "error");
    } finally {
      setConfirmDelete(null);
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
      <Loader2 className="w-12 h-12 text-fuchsia-500 animate-spin" />
      <p className="text-teal-400 font-black tracking-widest animate-pulse uppercase">Sistem Senkronize Ediliyor...</p>
    </div>
  );

  return (
    <div className="space-y-10 pb-20 relative animate-in fade-in duration-700">
      
      {/* BİLDİRİM (TOAST) */}
      {notification && (
        <div className={`fixed top-10 right-10 z-[200] p-5 rounded-2xl border backdrop-blur-xl flex items-center gap-3 animate-in slide-in-from-right duration-300 shadow-2xl ${
          notification.type === 'success' ? 'bg-teal-500/10 border-teal-500 text-teal-400' : 'bg-red-500/10 border-red-500 text-red-400'
        }`}>
          <CheckCircle2 size={20} />
          <span className="font-bold uppercase text-[10px] tracking-widest">{notification.msg}</span>
        </div>
      )}

      <header className="flex flex-col gap-2 border-l-4 border-fuchsia-500 pl-6">
        <h1 className="text-5xl font-black text-white uppercase italic tracking-tighter">Terminal <span className="text-fuchsia-500">Admin</span></h1>
        <p className="text-teal-400/50 text-xs font-bold tracking-[0.4em] uppercase">Merkezi Kontrol Birimi</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        
        {/* KULLANICI YÖNETİMİ */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-[#0E153A]/80 border border-white/5 rounded-[2.5rem] overflow-hidden backdrop-blur-md shadow-2xl">
            <div className="p-8 bg-white/5 flex items-center justify-between border-b border-white/5">
              <div className="flex items-center gap-4">
                <Users className="text-fuchsia-500" />
                <h2 className="text-white font-black uppercase italic tracking-widest">Sistem Kullanıcıları</h2>
              </div>
              <span className="text-[10px] bg-teal-500/20 text-teal-400 px-3 py-1 rounded-full font-mono">DB_COUNT: {data.stats?.length || 0}</span>
            </div>

            <div className="divide-y divide-white/5">
              {data.stats?.length > 0 ? data.stats.map((user: any) => (
                <div key={user.id} className="p-8 flex items-center justify-between hover:bg-white/[0.02] transition-all group">
                  <div className="flex items-center gap-6">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-teal-500/20 to-fuchsia-600/20 border border-white/10 flex items-center justify-center text-white font-black text-xl group-hover:scale-105 transition-transform">
                      {user.name?.[0] || "U"}
                    </div>
                    <div>
                      <h3 className="text-white font-bold text-lg group-hover:text-fuchsia-400 transition-colors">{user.name}</h3>
                      <p className="text-xs text-teal-400/40 font-mono italic">{user.email}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-8">
                    <div className="text-right hidden sm:block">
                      <p className="text-[10px] text-teal-400/30 uppercase font-black">Başarı</p>
                      <p className="text-xl font-black text-white italic">{user.percentage}%</p>
                    </div>
                    <button 
                      onClick={() => setConfirmDelete(user.id)}
                      className="p-4 bg-red-500/10 text-red-500 rounded-2xl hover:bg-red-500 hover:text-white transition-all transform hover:rotate-12"
                    >
                      <Trash2 size={20} />
                    </button>
                  </div>
                </div>
              )) : (
                <div className="p-20 text-center text-white/10 uppercase tracking-[0.5em] font-black italic">Veritabanı Boş</div>
              )}
            </div>
          </div>
        </div>

        {/* MESAJ MERKEZİ */}
        <div className="bg-[#0E153A]/40 border border-white/5 rounded-[2.5rem] p-8 space-y-6 shadow-xl">
          <h3 className="text-teal-400 font-black uppercase text-xs tracking-widest flex items-center gap-2">
            <MessageSquare size={16} /> Gelen İletişim
          </h3>
          <div className="space-y-4 max-h-[600px] overflow-y-auto pr-2 scrollbar-hide">
            {data.messages?.length > 0 ? data.messages.map((m: any) => (
              <div 
                key={m.id} 
                onClick={() => setSelectedMessage(m)}
                className="p-5 bg-white/5 rounded-2xl border-l-4 border-fuchsia-500 hover:bg-white/10 cursor-pointer transition-all group"
              >
                <div className="flex justify-between items-start mb-2">
                  <p className="text-fuchsia-400 font-bold text-xs group-hover:text-fuchsia-300">{m.name}</p>
                  <Eye size={14} className="text-white/20 group-hover:text-white" />
                </div>
                <p className="text-white/60 text-[11px] leading-relaxed line-clamp-2">{m.message}</p>
              </div>
            )) : (
              <p className="text-white/10 text-center py-10 uppercase text-[10px] tracking-widest italic">Mesaj bulunmuyor</p>
            )}
          </div>
        </div>
      </div>

      {/* SİLME ONAY MODALI */}
      {confirmDelete && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-[#0E153A] border border-red-500/30 p-10 rounded-[3rem] max-w-md w-full text-center shadow-[0_0_100px_rgba(239,68,68,0.1)]">
            <div className="w-20 h-20 bg-red-500/10 text-red-500 rounded-full flex items-center justify-center mx-auto mb-6">
              <AlertTriangle size={40} />
            </div>
            <h2 className="text-white text-2xl font-black uppercase italic mb-2 tracking-tighter">İmha Protokolü</h2>
            <p className="text-white/50 text-sm mb-8">Bu kullanıcıyı ve bağlı tüm verileri kalıcı olarak silmek istediğinizden emin misiniz?</p>
            <div className="flex gap-4">
              <button onClick={() => setConfirmDelete(null)} className="flex-1 p-4 bg-white/5 text-white font-bold rounded-2xl hover:bg-white/10 transition-all uppercase tracking-widest text-[10px]">İptal</button>
              <button onClick={handleDelete} className="flex-1 p-4 bg-red-600 text-white font-black rounded-2xl hover:bg-red-500 shadow-lg shadow-red-500/20 transition-all uppercase tracking-widest text-[10px]">Onayla</button>
            </div>
          </div>
        </div>
      )}

      {/* MESAJ OKUMA MODALI */}
      {selectedMessage && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center p-6 bg-black/90 backdrop-blur-xl animate-in fade-in zoom-in duration-300">
          <div className="bg-[#0E153A] border border-teal-400/30 p-10 rounded-[3rem] max-w-lg w-full shadow-[0_0_80px_rgba(45,212,191,0.1)]">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h2 className="text-fuchsia-400 font-black text-2xl italic tracking-tighter uppercase">{selectedMessage.name}</h2>
                <p className="text-teal-400/40 text-xs font-mono">{selectedMessage.email}</p>
              </div>
              <button onClick={() => setSelectedMessage(null)} className="p-2 hover:bg-white/10 rounded-full transition-all text-white">
                <X size={24} />
              </button>
            </div>
            <div className="bg-black/20 p-6 rounded-2xl border border-white/5">
              <p className="text-white/80 leading-relaxed text-sm italic">"{selectedMessage.message}"</p>
            </div>
            <div className="mt-8 pt-6 border-t border-white/5 text-right text-[10px] text-white/20 font-mono">
              Tarih: {new Date(selectedMessage.createdAt).toLocaleString()}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}